import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]

def f(g):
    vals=[v for row in g for v in row]
    bg=max(set(vals),key=vals.count)
    cells=[(i,j) for i,row in enumerate(g) for j,v in enumerate(row) if v!=bg]
    if not cells: return [row[:] for row in g]
    r0,r1=min(i for i,_ in cells),max(i for i,_ in cells)
    c0,c1=min(j for _,j in cells),max(j for _,j in cells)
    out=[row[:] for row in g]
    for i in range(r0,r1+1):
        for j in range(c0,c1+1):
            if out[i][j]==bg and (i in (r0,r1) or j in (c0,c1)):
                out[i][j]=2
    return out

for k in ['Demo pair 1 input','Demo pair 2 input']:
    o=k.replace('input','output')
    print(k, f(G[k])==G[o])
import json
print(json.dumps(f(G['Test input'])))
